    {
      "id": "commits_to_a_specific_action_quickly",
      "verdict": "met",
      "justification": "The response immediately commits: “I would order an immediate rollback of the new launch,” followed by instructions to Engineering to execute it and monitor recovery."
    },
    {
      "id": "distinguishes_reversible_from_expensive_to_reverse",
      "verdict": "met",
      "justification": "It frames the rollback as a temporary pause that can be re-enabled after a proper fix, while contrasting that with customer trust lost through prolonged incorrect signals, which it says is “far harder to win back.”"
    },
    {
      "id": "weighs_ongoing_harm_against_launch_momentum",
      "verdict": "met",
      "justification": "The response directly weighs the publicly announced launch’s “PR embarrassment” against several days of broken core functionality, compounding support burden, and damage to existing-customer trust, concluding the former is temporary and less severe."
    },
    {
      "id": "avoids_betting_on_unvalidated_fast_fix",
      "verdict": "met",
      "justification": "Rather than advocating a rushed patch, it proposes stopping impact through rollback and giving Engineering several days to “build, thoroughly test, and QA the proper scoping fix.”"
    },
    {
      "id": "proposes_concrete_next_step",
      "verdict": "met",
      "justification": "It provides concrete follow-through: verify signals return to baseline, give Support customer scripts, update the public status page, build and test the proper fix, brief leadership, and notify customers when the integration is re-enabled."
    }
  ]
